    const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
    const l = input[0];
    const r = input[1];

    // brute force for small ranges
    if (r - l <= 200000) {
        const { best } = bestInRange(l, r);
        console.log(best.toString());
        return;
    }

    // candidate-based search for large ranges
    let best = weight(l);
    let bestN = l;

    function tryN(n) {
        if (n < l || n > r) return;
        let w = weight(n);
        if (w > best) {
            best = w;
            bestN = n;
        }
    }

    // check boundaries and neighbors
    for (let d = 0; d <= 100; d++) {
        tryN(l + d);
        tryN(r - d);
    }

    // generate candidates by making prefix all '9's
    function genCandidates(x) {
        let s = x.toString();
        for (let i = 0; i < s.length; i++) {
            if (s[i] !== '9') {
                let t = '9'.repeat(i + 1);
                if (i + 1 < s.length) t += s.slice(i + 1);
                tryN(Number(t));
            }
        }
    }

    genCandidates(l);
    genCandidates(r);

    // small brute force around bestN to refine
    const span = 200000;
    let left = Math.max(l, bestN - span);
    let right = Math.min(r, bestN + span);
    const { best: refined } = bestInRange(left, right);
    if (refined > best) best = refined;

    console.log(best.toString());
}

